import {examArchiveKey,validExam,examReady,grade} from './workshop-exam-model.mjs';
export const retryArchiveKey='mecanica.workshop.examRetries.v1';
function read(storage,key){try{const rows=JSON.parse(storage.getItem(key)||'[]'),ids=new Set();return Array.isArray(rows)?rows.filter(e=>{if(!validExam(e)||!Number.isFinite(Date.parse(e.finished))||!e.cases.every(c=>c.submitted&&examReady(c))||ids.has(e.id))return false;ids.add(e.id);return true;}).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished)):[];}catch{return [];}}
export const completedExams=storage=>read(storage,examArchiveKey).filter(e=>!e.retryOf);
export const completedRetries=storage=>read(storage,retryArchiveKey).filter(e=>typeof e.retryOf==='string'&&Number.isInteger(e.retryIndex)&&e.retryIndex>=0&&e.retryIndex<4);
export function makeRetry(original,index){if(!original.finished||!original.cases[index]||grade(original.cases[index]).score===100)throw Error('No failed case');const e=structuredClone(original);e.id=crypto.randomUUID();e.started=new Date().toISOString();e.finished=null;e.index=index;e.retryOf=original.id;e.retryIndex=index;e.cases[index]={kind:original.cases[index].kind,fault:original.cases[index].fault,readings:[],diagnosis:'',submitted:false};return e;}
export function saveRetry(storage,e){if(!e.retryOf||!e.finished||!e.cases.every(c=>c.submitted&&examReady(c)))return;const rows=completedRetries(storage);if(!rows.some(r=>r.id===e.id))rows.push(e);storage.setItem(retryArchiveKey,JSON.stringify(rows.slice(-100)));}
export function mastery(exams,retries=[]){const groups=new Map();function collect(e,index,retry){const c=e.cases[index],g=grade(c);const record=(type,id,correct)=>{const key=c.kind+':'+type+':'+id;const s=groups.get(key)??{key,kind:c.kind,type,id,exams:[],retries:[]};s[retry?'retries':'exams'].push(correct);groups.set(key,s);};for(const id of new Set(g.readings.map(r=>r.id)))record('measurement',id,g.readings.filter(r=>r.id===id).every(r=>r.correct));record('diagnosis',c.fault,g.diagnosis);}for(const e of exams)for(let i=0;i<4;i++)collect(e,i,false);for(const e of retries)collect(e,e.retryIndex,true);return [...groups.values()].map(s=>({...s,status:s.exams.length<3?'early':s.exams.slice(-3).every(Boolean)?'consistent':'practice'}));}
